# — the definition of what counts as a change belongs in the footnote, not on the panel.
#
# ⛔ PERIOD-MEAN LINES WERE TRIED AND REMOVED. PJ, 16 Aug: "don't add to the figure - mess it up".
# The period means (0.68/yr before 2010, 1.13/yr from 2010) live in the footnote notes instead.
#
# ➕ PANEL B, CUMULATIVE. PJ, 16 Aug: "why not try the cumulative panel - there is a consistency
# issue across the figures - I can add health warnings in the text." Adjacent Ch2 figures (2.12,
# 2.13, 2.15) all carry a second panel, so a single-panel 2.14 sits oddly among them.
#
# ⛔ WHY CUMULATIVE AND NOT A BREAK PANEL. A Poisson sup-LR sweep — the count-appropriate
# equivalent of the Chow F-sweep used in 2.15's Panel B — finds NO IDENTIFIED BREAK:
#   peak at 2001, LR = 14.36, against a permutation-null 90th percentile of 14.41  ->  p = 0.10.
# Drawing that sweep would show a curve failing its own significance threshold. ⚠ It would also
# peak at 2001, NOT at 2010, where LR is only 2.42 — one of the weakest splits in the series.
# A cumulative curve shows the same acceleration WITHOUT asserting a date or a test.
#
# ⚠ THE HONEST RISK OF A CUMULATIVE PANEL: it only ever rises, so it can read as a finding when it
# is arithmetic. The informative feature is the SLOPE. The straight reference chord is therefore
# not decoration — it is what a CONSTANT rate over the whole window would look like, so the
# reader can see where the series runs below and above it. Without it the panel would be rhetoric.
#
# ⛔ NOT the quango/NDPB series, which is in machinery_churn but is COUNTER-CYCLICAL and is not in
# the composite. Plotting both would invite the reader to add them.
# ⛔ NO break test on this series. It is a sparse count (19 non-zero years of 46, values 1-6); a
# sup-F on it would be reporting the position of two or three bars.

suppressPackageStartupMessages({library(ggplot2); library(readr); library(dplyr); library(patchwork)})

P   <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), "../..")) else getwd()
})
WS  <- file.path(P, "data_workspace_2026-07")
MCH <- file.path(WS, "machinery_churn")

d <- read_csv(file.path(MCH, "data/departmental_churn_1979_2025.csv"), show_col_types = FALSE)
ev <- read_csv(file.path(MCH, "data/departmental_events.csv"), show_col_types = FALSE)

# ⛔ TRIPWIRE, not decoration. Every event must carry a named source. The figure draws all bars
# solid, so an UNVERIFIED event would be silently presented as evidence we have. If one ever
# reappears, fail here rather than plot it.
unver <- ev |> filter(verification == "UNVERIFIED")
if (nrow(unver) > 0) {
  stop("UNVERIFIED events present (", nrow(unver), "): ",
       paste(unver$year, unver$department, collapse = "; "),
       "\n  -> either verify them, or restore the hollow-bar marking before plotting.")
}
stopifnot(sum(d$dept_churn) == nrow(ev))
cat(sprintf("series: %d events, %d non-zero years; all verified\n",
            sum(d$dept_churn), sum(d$dept_churn > 0)))

base <- theme_minimal(base_size = 9) +
  theme(legend.position = "none",
        panel.grid.minor = element_blank(),
        panel.grid.major.x = element_blank(),
        panel.grid.major.y = element_line(colour = "grey90", linewidth = 0.3),
        axis.title.y = element_text(size = 8))

# ⛔ 17 Aug: the upper limit was 2024.6 and silently CLIPPED the new 2025 point — ggplot drops
#    out-of-range data with a warning, not an error. Extended with the series.
XS <- scale_x_continuous(breaks = seq(1980, 2025, 5), limits = c(1978.4, 2025.6))
ptitle <- function(x) theme(
  plot.subtitle = element_text(face = "italic", colour = "grey30", size = 9),
  plot.tag      = element_text(face = "bold", size = 11))

pA <- ggplot(d, aes(year)) +
  geom_col(aes(y = dept_churn), width = 0.78, fill = "grey28", colour = NA) +
  XS +
  scale_y_continuous(breaks = seq(0, 6, 2), limits = c(0, 6.3), expand = c(0, 0)) +
  labs(tag = "A", subtitle = "Changes per year", x = NULL, y = "Departmental changes") +
  base + ptitle()

cum <- d |> arrange(year) |> mutate(cum = cumsum(dept_churn))
chord <- data.frame(x = c(min(cum$year), max(cum$year)), y = c(0, sum(d$dept_churn)))

pB <- ggplot(cum, aes(year, cum)) +
  geom_line(data = chord, aes(x, y), colour = "grey62", linewidth = 0.45,
            linetype = "42", inherit.aes = FALSE) +
  geom_line(colour = "grey15", linewidth = 0.7) +
  # ⚠ The chord is diagonal, so horizontal text placed NEAR it gets struck through. It sits in the
  # empty upper-left instead, where the chord is still low (it reaches only ~16 by 1998) and the
  # solid line is far below. Two earlier placements were rejected: the segment midpoint read as
  # labelling the SOLID line, and just-above-the-chord was crossed by it.
  annotate("text", x = 1980.4, y = 21.5, label = "constant rate over the window",
           size = 2.7, colour = "grey45", hjust = 0) +
  XS +
  scale_y_continuous(breaks = seq(0, 40, 10), limits = c(0, 40), expand = c(0, 0)) +
  labs(tag = "B", subtitle = "Cumulative total", x = NULL, y = "Cumulative changes") +
  base + ptitle()

fig <- (pA / pB) +
  plot_layout(heights = c(1.15, 1)) +
  plot_annotation(
    title = "Figure 2.12: Changes to the machinery of central government, 1979–2025",
    theme = theme(plot.title = element_text(face = "bold", size = 11.5,
                                            margin = margin(b = 10))))

out <- file.path(MCH, "figures/fig_2_12_machinery_churn_1979_2025.png")
ggsave(out, fig, width = 6.5, height = 5.2, dpi = 300, bg = "white")
cat("wrote", out, "\n")
